/* The color catalogue is the source for swatches, exports and usage examples. */
const brandCore=[['Violet','#6646D8','Primary brand color and light-mode actions.'],['Canvas','#FAF9F7','The primary light background.'],['Ink','#221F2C','Headings, reading text and dark brand surfaces.']];
const brandAccents=[['Deep violet','#4D2FA2','Strong expression and dark violet pairings.'],['Lavender','#D9C9F7','Soft brand panels with Ink or Deep violet text.'],['Orchid','#A98BE6','Illustration and supporting graphic detail.'],['Cobalt','#3153C4','Secondary brand compositions and data series.'],['Sky','#C6DAF5','Soft blue panels with Ink or Cobalt text.'],['Coral','#E9785F','Warm expressive moments, with Ink text.'],['Peach','#F8C6B3','Warm background pairings with Plum or Ink.'],['Amber','#F2BB55','Editorial highlights and brand compositions.'],['Ochre','#946400','Dark amber counterpart for light surfaces.'],['Raspberry','#AA3F66','Expressive emphasis paired with Rose.'],['Rose','#F3BDD0','Soft expressive surfaces with Ink or Raspberry.'],['Plum','#603B69','Dark expressive counterpart to Peach and Lilac.'],['Lilac','#E9D9EF','Quiet supporting background with dark text.']];
const brandNeutrals=[['Neutral 1000','#17151D','Dark canvas.'],['Neutral 950','#221F2C','Ink.'],['Neutral 900','#2E2938','Dark elevated surfaces.'],['Neutral 800','#46404F','Strong boundaries.'],['Neutral 700','#625B6E','Secondary light-theme text.'],['Neutral 600','#797083','Input boundaries.'],['Neutral 500','#918A9D','Dark input boundaries.'],['Neutral 400','#BFB9CA','Secondary dark-theme text.'],['Neutral 300','#D4CEDD','Supporting neutral.'],['Neutral 200','#DED9E5','Decorative light divider.'],['Neutral 100','#EEEAF3','Soft surface.'],['Neutral 50','#F6F3FA','Primary dark-theme text.'],['Neutral 0','#FFFFFF','White elevated surface.']];
function swatchInk(bg){return +ratio(bg,'#221F2C')>=+ratio(bg,'#FFFFFF')?'#221F2C':'#FFFFFF'}
function catalogGroup(name,items,kind){return `<div class="catalog-group catalog-${kind}"><div class="catalog-label"><h3>${name}</h3><span>${items.length} colors</span></div><div class="catalog-scroll" role="region" aria-label="${name} palette" tabindex="0"><div class="catalog-wave" data-color-wave style="--count:${items.length}">${items.map(([n,h,u],i)=>`<button class="catalog-swatch" style="--slot:${i};--chip:${h};--chip-ink:${swatchInk(h)};--rise:0px" data-palette-index="${i}" data-palette-copy="${h}" aria-label="Copy ${n}, ${h}. ${u}"><span class="catalog-swatch-title">${n}</span><code>${h}</code><span class="catalog-swatch-use">${u}</span></button>`).join('')}</div></div></div>`}
function colorCatalogue(){return `<section class="color-catalogue"><div class="catalogue-heading"><span class="eyebrow">The color catalogue</span><h2>A focused core.<br>A wider world of color.</h2><p>Move across a row to explore. Select a color to copy it.</p></div>${catalogGroup('Core colors',brandCore,'core')}${catalogGroup('Accent colors',brandAccents,'accent')}${catalogGroup('Neutrals',brandNeutrals,'neutral')}<div class="catalog-caption"><span>Names and hex values appear on hover or keyboard focus.</span><span>On touch screens, swipe the row and tap a color.</span></div></section>`}
function accentSpecifications(){return specTable('Accents, used with intention.','The core carries recognition. Accents extend the expression. They do not create new interface states.',['Family','Colors','Approved text / background','Usage'],[
['Violet',colorChip('#4D2FA2')+colorChip('#D9C9F7')+colorChip('#A98BE6'),'Ink on Lavender; White on Deep violet.','Brand panels, artwork, selected expression and tonal depth.'],['Blue',colorChip('#3153C4')+colorChip('#C6DAF5'),'Cobalt on Sky; Ink on Sky.','Supporting compositions, data visualization and secondary artwork.'],['Warm',colorChip('#E9785F')+colorChip('#F8C6B3')+colorChip('#F2BB55')+colorChip('#946400'),'Ink on Coral, Peach or Amber.','Launch moments, editorial emphasis and warmer brand compositions.'],['Rose / Plum',colorChip('#AA3F66')+colorChip('#F3BDD0')+colorChip('#603B69')+colorChip('#E9D9EF'),'Plum on Peach; Ink on Rose or Lilac.','Editorial details, imagery framing and complementary pairings.']])}
function catalogColorExperience(){return architecturalHero('Color','hero-color')+statementScene('A clear foundation. A wider palette. Different colors, working together.','color-words')+colorCatalogue()+colorPlay()+visibleSpecs('color')+accentSpecifications()+usage('Use color to guide the work.','Keep most dashboard surfaces neutral. Use violet for the main action; bring accents into artwork and deliberate supporting moments.',[['Contrast & pairings',`<p>White on Violet: ${ratio('#FFFFFF','#6646D8')}:1. Ink on Lavender: ${ratio('#221F2C','#D9C9F7')}:1. Ink on Peach: ${ratio('#221F2C','#F8C6B3')}:1. These pairs pass AA normal-text contrast. Check any new pairing before using it for reading text.</p>`],['Brand accents & product status','<p>Accent colors express the brand. Semantic colors communicate success, warning, error and information. Do not swap them arbitrarily. Pair every status with an icon or label.</p>'],['Take the palette','<a class="text-link" href="assets/tokens.json" download>Download theme tokens</a> · <a class="text-link" href="assets/palette.json" download>Download the full color catalogue</a>']])+next('color')}
function bindColorCatalogue(root){const cleanup=[];$$('[data-color-wave]',root).forEach(row=>{const chips=$$('.catalog-swatch',row),scroll=row.parentElement;let active=-1;const small=()=>innerWidth<650;const setActive=index=>{if(index===active)return;active=index;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;chips.forEach((chip,i)=>{const d=Math.abs(i-index),peak=row.closest('.catalog-neutral')?110:145;const lift=index<0?0:d===0?peak:d===1?peak*.65:d===2?peak*.35:d===3?peak*.13:0;chip.style.setProperty('--rise',lift+'px');chip.style.setProperty('--tilt',!reduced&&d===0?'-1deg':'0deg');chip.style.zIndex=String(index<0?i+1:d===0?100:50-d);chip.classList.toggle('is-active',i===index)})};const move=e=>{if(e.pointerType==='touch')return;const r=row.getBoundingClientRect();setActive(Math.max(0,Math.min(chips.length-1,Math.floor((e.clientX-r.left)/r.width*chips.length))))};const leave=()=>{if(!row.contains(document.activeElement))setActive(-1)};const focus=e=>{const chip=e.target.closest('[data-palette-index]');if(chip)setActive(+chip.dataset.paletteIndex)};const focusout=()=>requestAnimationFrame(()=>{if(!row.contains(document.activeElement))setActive(-1)});const click=async e=>{const target=e.target.closest('[data-palette-copy]');if(!target)return;const index=e.detail===0?+target.dataset.paletteIndex:active>=0?active:+target.dataset.paletteIndex;setActive(index);const hex=chips[index].dataset.paletteCopy;try{await navigator.clipboard.writeText(hex);toast(`${chips[index].querySelector('.catalog-swatch-title').textContent} · ${hex} copied`)}catch(err){toast(hex)}};const touch=e=>{if(e.pointerType!=='touch')return;const r=row.getBoundingClientRect();setActive(Math.max(0,Math.min(chips.length-1,Math.floor((e.clientX-r.left)/r.width*chips.length))))};row.addEventListener('pointermove',move);row.addEventListener('pointerleave',leave);row.addEventListener('pointerdown',touch);row.addEventListener('focusin',focus);row.addEventListener('focusout',focusout);row.addEventListener('click',click);cleanup.push(()=>{row.removeEventListener('pointermove',move);row.removeEventListener('pointerleave',leave);row.removeEventListener('pointerdown',touch);row.removeEventListener('focusin',focus);row.removeEventListener('focusout',focusout);row.removeEventListener('click',click)})});return ()=>cleanup.forEach(f=>f())}
